  `address_line_2` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `postal_code` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `state` varchar(100) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `company` varchar(200) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `job_title` varchar(200) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `source` varchar(30) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'manual' COMMENT 'form|import|woocommerce|manual|registration',
  `status` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'lead' COMMENT 'lead|prospect|student|alumni',
  `contact_type` enum('lead','student','customer','partner','other') COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'lead',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
