\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-segment\"><!-- wp:group {\"className\":\"atora-home-segment-head\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-segment-head\"><!-- wp:paragraph {\"className\":\"atora-home-segment-kicker\"} -->\n<p class=\"atora-home-segment-kicker\">FORMACIÓN CORPORATIVA</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Capacitación medible para equipos</h3>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:list {\"className\":\"atora-home-bullets\"} -->\n<ul class=\"wp-block-list atora-home-bullets\"><!-- wp:list-item -->\n<li>Rutas por área y cargo, con cumplimiento y vencimientos</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Contenido SCORM heredado sin reconvertir</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Analítica por sede y por gerencia</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"wide\",\"className\":\"atora-home-section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide atora-home-section\"><!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"24px\"}}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-top\"><!-- wp:column {\"width\":\"55%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:55%\"><!-- wp:paragraph {\"className\":\"atora-home-kicker\"} -->\n<p class=\"atora-home-kicker\">TECNOLOGÍA Y CONFIANZA</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"fontFamily\":\"var:preset|font-family|sora\",\"fontSize\":\"clamp(2rem, 4.6vw, 3.4rem)\",\"fontWeight\":\"800\",\"letterSpacing\":\"-0.03em\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-family:var(--wp--preset--font-family--sora);fon