--></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"atora-home-trust-item\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group atora-home-trust-item\"><!-- wp:group {\"className\":\"atora-home-dot\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-dot\"></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"className\":\"atora-home-trust-title\"} -->\n<p class=\"atora-home-trust-title\"><strong>Multi-institución desde el diseño</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">Una arquitectura preparada para varias sedes o instituciones con administración separada.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"atora-home-trust-item\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group atora-home-trust-item\"><!-- wp:group {\"className\":\"atora-home-dot\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-dot\"></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"className\":\"atora-home-trust-title\"} -->\n<p class=\"atora-home-trust-title\"><strong>Interoperable</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">SCORM 1.2, H5P y puentes LTI para convivir con Canvas o Moodle sin quedar atrapado.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"45%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:45%\"><!-- wp:group 