\">\n			<!-- wp:list-item -->\n			<li>WordPress abierto</li>\n			<!-- /wp:list-item -->\n			<!-- wp:list-item -->\n			<li>SCORM 1.2</li>\n			<!-- /wp:list-item -->\n			<!-- wp:list-item -->\n			<li>H5P</li>\n			<!-- /wp:list-item -->\n			<!-- wp:list-item -->\n			<li>Streaming HLS protegido</li>\n			<!-- /wp:list-item -->\n			<!-- wp:list-item -->\n			<li>Multi-institución</li>\n			<!-- /wp:list-item -->\n			<!-- wp:list-item -->\n			<li>SSO opcional</li>\n			<!-- /wp:list-item -->\n			<!-- wp:list-item -->\n			<li>App Android / iOS</li>\n			<!-- /wp:list-item -->\n		</ul>\n		<!-- /wp:list -->\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"align\":\"wide\",\"className\":\"atora-home-section\",\"layout\":{\"type\":\"constrained\"}} -->\n	<div class=\"wp-block-group alignwide atora-home-section\">\n		<!-- wp:paragraph {\"className\":\"atora-home-kicker\"} -->\n		<p class=\"atora-home-kicker\">LA PLATAFORMA</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"level\":2,\"style\":{\"typography\":{\"fontFamily\":\"var:preset|font-family|sora\",\"fontSize\":\"clamp(2rem, 4.4vw, 3.2rem)\",\"fontWeight\":\"800\",\"letterSpacing\":\"-0.03em\"}}} -->\n		<h2 style=\"font-family:var(--wp--preset--font-family--sora);font-size:clamp(2rem, 4.4vw, 3.2rem);font-weight:800;letter-spacing:-0.03em\">Un solo sistema para enseñar, evaluar, acompañar y administrar</h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"textColor\":\"ink-2\",\"style\":{\"typography\":{\"fontSize\":\"1.08rem\",\"lineHeight\":\"1.7\"}}} -->\n		<p class=\"has-ink-2-color has-text-color\" style=\"font-size:1.08rem;line-height:1.7\">Cada módulo nace del uso real en una academia en producción. Se instalan juntos y se activan según lo que tu institución necesita.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:group {\"className\":\"atora-home-feature-grid\",\"layout\":{\"type\":\"constrained\"}} -->\n		<div class=\"wp-block-group atora-home-feature-grid\">\n			<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"16px\",\"left\":\"16px\"}}}} -->\n			<div class=\"wp-block-columns\">\n				<!-- wp:column -->\n				<div class=\"wp-block-column\">\n					<!-- wp:group {\"className\":\"atora-home-feature-card\",\"layout\":{\"type\":\"constrained\"}} -->\n					<div class=\"wp-block-group atora-home-feature-card\">\n						<!-- wp:html -->\n						\n						<!-- /wp:html -->\n						<!-- wp:heading {\"level\":3} -->\n						<h3>Cursos y programas</h3>\n						<!-- /wp:heading -->\n						<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n						<p class=\"has-ink-2-color has-text-color\">Lecciones con video, guías, cuestionarios y entregas abiertas. Programas, diplomados y cohortes.</p>\n						<!-- /wp:paragraph -->\n					</div>\n					<!-- /wp:group -->\n				</div>\n				<!-- /wp:column -->\n\n				<!-- wp:column -->\n				<div class=\"wp-block-column\">\n					<!-- wp:group {\"className\":\"atora-home-feature-card\",\"layout\":{\"type\":\"constrained\"}} -->\n					<div class=\"wp-block-group atora-home-feature-card\">\n						<!-- wp:html -->\n						\n						<!-- /wp:html -->\n						<!-- wp:heading {\"level\":3} -->\n						<h3>Rúbricas y calificación</h3>\n						<!-- /wp:heading -->\n						<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n						<p class=\"has-ink-2-color has-text-color\">Escalas propias, pesos y ejemplares. La IA sugiere la nota y detecta contenido generado; el docente decide.</p>\n						<!-- /wp:paragraph -->\n					</div>\n					<!-- /wp:group -->\n				</div>\n				<!-- /wp:column -->\n\n				<!-- wp:column -->\n				<div class=\"wp-block-column\">\n					<!-- wp:group {\"className\":\"atora-home-feature-card\",\"layout\":{\"type\":\"constrained\"}} -->\n					<div class=\"wp-block-group atora-home-feature-card\">\n						<!-- wp:html -->\n						\n						<!-- /wp:html -->\n						<!-- wp:heading {\"level\":3} -->\n						<h3>Grupos y cohortes</h3>\n						<!-- /wp:heading -->\n						<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n						<p class=\"has-ink-2-color has-text-color\">Separa usuarios por programa, cohorte y curso. Invitaciones masivas para instituciones.</p>\n						<!-- /wp:paragraph -->\n					</div>\n					<!-- /wp:group -->\n				</div>\n				<!-- /wp:column -->\n\n				<!-- wp:column -->\n				<div class=\"wp-block-column\">\n					<!-- wp:group {\"className\":\"atora-home-feature-card is-highlight\",\"layout\":{\"type\":\"constrained\"}} -->\n					<div class=\"wp-block-group atora-home-feature-card is-highlight\">\n						<!-- wp:html -->\n						\n						<!-- /wp:html -->\n						<!-- wp:heading {\"level\":3} -->\n						<h3>Analítica de riesgo</h3>\n						<!-- /wp:heading -->\n						<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n						<p class=\"has-ink-2-color has-text-color\">Puntaje de riesgo por estudiante y reportes por cohorte para intervenir antes de la deserción.</p>\n						<!-- /wp:paragraph -->\n					</div>\n					<!-- /wp:group -->\n				</div>\n				<!-- /wp:column -->\n			</div>\n			<!-- /wp:columns -->\n\n			<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"16px\",\"left\":\"16px\"}}}} -->\n			<div class=\"wp-block-columns\">\n				<!-- wp:column -->\n				<div class=\"wp-block-column\">\n					<!-- wp:group {\"className\":\"atora-home-feature-card\",\"layout\":{\"type\":\"constrained\"}} -->\n					<div class=\"wp-block-group atora-home-feature-card\">\n						<!-- wp:html -->\n						\n						<!-- /wp:html -->\n						<!-- wp:heading {\"level\":3} -->\n						<h3>Video protegido</h3>\n						<!-- /wp:heading -->\n						<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n						<p class=\"has-ink-2-color has-text-color\">Streaming HLS con tokens y marca de agua por estudiante. Compatible con YouTube, Vimeo, Drive y CDN.</p>\n						<!-- /wp:paragraph -->\n					</div>\n					<!-- /wp:group -->\n				</div>\n				<!-- /wp:column -->\n\n				<!-- wp:column -->\n				<div class=\"wp-block-column\">\n					<!-- wp:group {\"className\":\"atora-home-feature-card\",\"layout\":{\"type\":\"constrained\"}} -->\n					<div class=\"wp-block-g