a class=\"wp-block-button__link has-bg-2-color has-text-color wp-element-button\" href=\"#\" style=\"font-weight:800\">Ver la academia de prueba</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n\n<!-- wp:separator {\"className\":\"atora-home-hero-sep\",\"backgroundColor\":\"line\"} -->\n<hr class=\"wp-block-separator has-text-color has-line-color has-alpha-channel-opacity has-line-background-color has-background atora-home-hero-sep\"/>\n<!-- /wp:separator -->\n\n<!-- wp:columns {\"className\":\"atora-home-hero-stats\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"24px\"}}}} -->\n<div class=\"wp-block-columns atora-home-hero-stats\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph {\"className\":\"atora-home-stat\"} -->\n<p class=\"atora-home-stat\"><strong>26</strong><br>módulos integrados</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph {\"className\":\"atora-home-stat\"} -->\n<p class=\"atora-home-stat\"><strong>12</strong><br>idiomas</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph {\"className\":\"atora-home-stat\"} -->\n<p class=\"atora-home-stat\"><strong>80%</strong><br>de uso previsto en móvil</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph {\"className\":\"atora-home-stat\"} -->\n<p class=\"atora-home-stat\"><strong>0</strong><br>lock-in: datos y código en tu casa</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"42%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:42%\"><!-- wp:group {\"className\":\"atora-home-dashboard\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-dashboard\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"12px\"}},\"layout\":{\"ty