}} -->\n<div class=\"wp-block-group alignwide atora-home-section\"><!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"24px\"}}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-top\"><!-- wp:column {\"width\":\"55%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:55%\"><!-- wp:paragraph {\"className\":\"atora-home-kicker\"} -->\n<p class=\"atora-home-kicker\">TECNOLOGÍA Y CONFIANZA</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"fontFamily\":\"var:preset|font-family|sora\",\"fontSize\":\"clamp(2rem, 4.6vw, 3.4rem)\",\"fontWeight\":\"800\",\"letterSpacing\":\"-0.03em\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-family:var(--wp--preset--font-family--sora);font-size:clamp(2rem, 4.6vw, 3.4rem);font-weight:800;letter-spacing:-0.03em\">Abierto, auditado y sin dependencia de terceros</h2>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"className\":\"atora-home-trust\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-trust\"><!-- wp:group {\"className\":\"atora-home-trust-item\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group atora-home-trust-item\"><!-- wp:group {\"className\":\"atora-home-dot\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-dot\"></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"className\":\"atora-home-trust-title\"} -->\n<p class=\"atora-home-trust-title\"><strong>Tus datos, tu servidor</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">Se instala en la infraestructura que tú eliges. Si un día te vas, te llevas todo.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"atora-home-trust-item\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group atora-home-trust-item\"><!-- wp:group {\"className\":\"atora-home-dot\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-dot\"></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"className\":\"atora-home-trust-title\"} -->\n<p class=\"atora-home-trust-title\"><strong>Seguridad auditada</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">Auditorías externas y series de endurecimiento sobre REST, autenticación y permisos.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"atora-home-trust-item\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group atora-home-trust-item\"><!-- wp:group {\"className\":\"atora-home-dot\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-dot\"></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"className\":\"atora-home-trust-title\"} -->\n<p class=\"atora-home-trust-title\"><strong>Multi-institución desde el diseño</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">Una arquitectura preparada para varias sedes o instituciones con administración separada.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"atora-home-trust-item\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group atora-home-trust-item\"><!-- wp:group {\"className\":\"atora-home-dot\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-dot\"></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"className\":\"atora-home-trust-title\"} -->\n<p class=\"atora-home-trust-title\"><strong>Interoperable</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">SCORM 1.2, H5P y puentes LTI para convivir con Canvas o Moodle sin quedar atrapado.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"45%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:45%\"><!-- wp:group {\"className\":\"atora-home-arch\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-arch\"><!-- wp:paragraph {\"className\":\"atora-home-arch-kicker\"} -->\n<p class=\"atora-home-arch-kicker\">ARQUITECTURA DEL ECOSISTEMA</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"atora-home-arch-item\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"space-between\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group atora-home-arch-item\"><!-- wp:paragraph -->\n<p><strong>App móvil Android / iOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">offline · estudiante y docente</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"atora-home-arch-item\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"space-between\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group atora-home-arch-item\"><!-- wp:paragraph -->\n<p><strong>Tema ATORA</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">sitio público y academia</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"atora-home-arch-item is-active\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"space-between\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group atora-home-arch-item is-active\"><!-- wp:paragraph -->\n<p><strong>ATORA LMS + CRM</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>26 módulos · API REST</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"atora-home-arch-item\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"space-between\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group atora-home-arch-item\"><!-- wp:paragraph -->\n<p><strong>Streaming HLS · Biblioteca SCORM/H5P</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">microservicios</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"atora-home-arch-item\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"space-between\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group atora-home-arch-item\"><!-- wp:paragraph -->\n<p><strong>Tu servidor o colocation</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">WordPress · MySQL · CDN/WAF</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"atora-home-section atora-home-pricing\",\"backgroundColor\":\"bg-2\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull atora-home-section atora-home-pricing has-bg-2-background-color has-background\"><!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:paragraph {\"className\":\"atora-home-kicker\"} -->\n<p class=\"atora-home-kicker\">MODELO DE LICENCIA</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"fontFamily\":\"var:preset|font-family|sora\",\"fontSize\":\"clamp(2rem, 4.4vw, 3.2rem)\",\"fontWeight\":\"800\",\"letterSpacing\":\"-0.03em\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-family:var(--wp--preset--font-family--sora);font-size:clamp(2rem, 4.4vw, 3.2rem);font-weight:800;letter-spacing:-0.03em\">Un precio por estudiante, no por sorpresa</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.06rem\",\"lineHeight\":\"1.7\"}},\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\" style=\"font-size:1.06rem;line-height:1.7\">Instalación y soporte el primer año; después, una licencia anual proporcional a tu matrícula. Sin cobros por módulo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"16px\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"atora-home-price-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-price-card\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Academia</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">Hasta 100 estudiantes</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"atora-home-price\"} -->\n<h3 class=\"wp-block-heading atora-home-price\">Consultar</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Instalación en tu hosting</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Todos los módulos</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Soporte por correo</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"backgroundColor\":\"blue\",\"textColor\":\"bg-2\",\"style\":{\"typography\":{\"fontWeight\":\"800\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-bg-2-color has-blue-background-color has-text-color has-background wp-element-button\" href=\"#\" style=\"font-weight:800\">Hablemos</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"atora-home-price-card is-featured\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-price-card is-featured\"><!-- wp:paragraph {\"className\":\"atora-home-badge atora-home-badge-floating\"} -->\n<p class=\"atora-home-badge atora-home-badge-floating\">MÁS SOLICITADO</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Institución</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">Hasta 1.500 estudiantes</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"atora-home-price\"} -->\n<h3 class=\"wp-block-heading atora-home-price\">Por estudiante <span class=\"atora-home-price-small\">/ año</span></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Servidor principal + espejo de respaldo</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Migración de cursos y usuarios</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Capacitación docente</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Soporte prioritario</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"backgroundColor\":\"amber\",\"textColor\":\"ink\",\"style\":{\"typography\":{\"fontWeight\":\"800\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-ink-color has-amber-background-color has-text-color has-background wp-element-button\" href=\"#\" style=\"font-weight:800\">Solicitar propuesta</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"atora-home-price-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-price-card\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Universidad</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">Hasta 10.000 por instancia</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"atora-home-price\"} -->\n<h3 class=\"wp-block-heading atora-home-price\">A medida</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Varias instancias federadas</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>SSO, LTI y analítica avanzada</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Producción audiovisual de clases (opcional)</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"backgroundColor\":\"blue\",\"textColor\":\"bg-2\",\"style\":{\"typography\":{\"fontWeight\":\"800\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-bg-2-color has-blue-background-color has-text-color has-background wp-element-button\" href=\"#\" style=\"font-weight:800\">Agendar reunión</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"wide\",\"className\":\"atora-home-section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide atora-home-section\"><!-- wp:paragraph {\"className\":\"atora-home-kicker\"} -->\n<p class=\"atora-home-kicker\">ACADEMIA DE PRUEBA</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"24px\"}}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"style\":{\"typography\":{\"fontFamily\":\"var:preset|font-family|sora\",\"fontSize\":\"clamp(2rem, 4.4vw, 3.2rem)\",\"fontWeight\":\"800\",\"letterSpacing\":\"-0.03em\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-family:var(--wp--preset--font-family--sora);font-size:clamp(2rem, 4.4vw, 3.2rem);font-weight:800;letter-spacing:-0.03em\">Míralo funcionando con cursos reales</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.05rem\",\"lineHeight\":\"1.7\"}},\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\" style=\"font-size:1.05rem;line-height:1.7\">ATORA Lab es una academia viva de comunicación y fotografía. Entra como estudiante y recorre la experiencia completa.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"34%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:34%\"><!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"right\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"backgroundColor\":\"blue\",\"textColor\":\"bg-2\",\"style\":{\"typography\":{\"fontWeight\":\"800\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-bg-2-color has-blue-background-color has-text-color has-background wp-element-button\" href=\"#\" style=\"font-weight:800\">Entrar a la academia</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:shortcode -->\n[atora_home_courses limit=\"8\"]\n<!-- /wp:shortcode -->\n\n<!-- wp:shortcode -->\n[atora_home_mentors intro=\"Nueve mentores con trayectoria real en periodismo, fotografía y comunicación.\"]\n<!-- /wp:shortcode --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"atora-home-quote\",\"backgroundColor\":\"blue\",\"textColor\":\"bg-2\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull atora-home-quote has-bg-2-color has-blue-background-color has-text-color has-background\"><!-- wp:group {\"align\":\"wide\",\"className\":\"atora-home-section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide atora-home-section\"><!-- wp:heading {\"style\":{\"typography\":{\"fontFamily\":\"var:preset|font-family|sora\",\"fontSize\":\"clamp(1.9rem, 3.6vw, 3rem)\",\"fontWeight\":\"800\",\"letterSpacing\":\"-0.03em\",\"lineHeight\":\"1.2\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-family:var(--wp--preset--font-family--sora);font-size:clamp(1.9rem, 3.6vw, 3rem);font-weight:800;letter-spacing:-0.03em;line-height:1.2\">“Encontré una formación seria, clara y profundamente útil para mi trabajo.”</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontWeight\":\"700\"}},\"textColor\":\"amber\"} -->\n<p class=\"has-amber-color has-text-color\" style=\"font-weight:700\">Participante · Comunicación visual y redes sociales</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"wide\",\"className\":\"atora-home-section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide atora-home-section\"><!-- wp:paragraph {\"className\":\"atora-home-kicker\"} -->\n<p class=\"atora-home-kicker\">PREGUNTAS DE INSTITUCIONES</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"fontFamily\":\"var:preset|font-family|sora\",\"fontSize\":\"clamp(2rem, 4.4vw, 3.2rem)\",\"fontWeight\":\"800\",\"letterSpacing\":\"-0.03em\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-family:var(--wp--preset--font-family--sora);font-size:clamp(2rem, 4.4vw, 3.2rem);font-weight:800;letter-spacing:-0.03em\">Lo que nos preguntan antes de decidir</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"24px\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:details {\"className\":\"atora-home-faq\"} -->\n<details class=\"wp-block-details atora-home-faq\"><summary>¿Podemos migrar nuestros cursos actuales?</summary><p>Sí. Se planifica una migración por etapas para minimizar interrupciones, validando cursos, usuarios y reportes críticos.</p></details>\n<!-- /wp:details -->\n\n<!-- wp:details {\"className\":\"atora-home-faq\"} -->\n<details class=\"wp-block-details atora-home-faq\"><summary>¿Funciona con poca conectividad?</summary><p>Sí. La experiencia móvil contempla descargas y sincronización cuando el usuario recupera conexión.</p></details>\n<!-- /wp:details -->\n\n<!-- wp:details {\"className\":\"atora-home-faq\"} -->\n<details class=\"wp-block-details atora-home-faq\"><summary>¿Incluye inicio de sesión institucional?</summary><p>Se puede integrar SSO según tu infraestructura (por ejemplo, Microsoft Entra) y políticas de acceso.</p></details>\n<!-- /wp:details --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:details {\"className\":\"atora-home-faq\"} -->\n<details class=\"wp-block-details atora-home-faq\"><summary>¿Dónde viven los datos?</summary><p>En la infraestructura que tú eliges: tu hosting, tu servidor o colocation. Tu institución conserva control sobre datos y backups.</p></details>\n<!-- /wp:details -->\n\n<!-- wp:details {\"className\":\"atora-home-faq\"} -->\n<details class=\"wp-block-details atora-home-faq\"><summary>¿Cuántos estudiantes soporta?</summary><p>Depende de la infraestructura. Se dimensiona por volumen, sedes e integraciones para asegurar estabilidad y desempeño.</p></details>\n<!-- /wp:details -->\n\n<!-- wp:details {\"className\":\"atora-home-faq\"} -->\n<details class=\"wp-block-details atora-home-faq\"><summary>¿Qué soporte hay para docentes?</summary><p>Capacitación, guía operativa y acompañamiento para adopción. La prioridad y canales dependen del plan.</p></details>\n<!-- /wp:details --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"atora-home-final\",\"backgroundColor\":\"blue-deep\",\"textColor\":\"bg-2\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull atora-home-final has-bg-2-color has-blue-deep-background-color has-text-color has-background\"><!-- wp:group {\"align\":\"wide\",\"className\":\"atora-home-section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide atora-home-section\"><!-- wp:paragraph {\"className\":\"atora-home-eyebrow atora-home-eyebrow-on-dark\"} -->\n<p class=\"atora-home-eyebrow atora-home-eyebrow-on-dark\">SIGUIENTE PASO</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"fontFamily\":\"var:preset|font-family|sora\",\"fontSize\":\"clamp(2.2rem, 5vw, 4rem)\",\"fontWeight\":\"900\",\"letterSpacing\":\"-0.03em\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-family:var(--wp--preset--font-family--sora);font-size:clamp(2.2rem, 5vw, 4rem);font-weight:900;letter-spacing:-0.03em\">Veamos ATORA con tus propios programas</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.05rem\",\"lineHeight\":\"1.7\"}}} -->\n<p style=\"font-size:1.05rem;line-height:1.7\">Agenda una demostración de 45 minutos. Traemos la plataforma cargada con un curso tuyo para que la evalúes con tu equipo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"left\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"backgroundColor\":\"amber\",\"textColor\":\"ink\",\"style\":{\"typography\":{\"fontWeight\":\"800\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-ink-color has-amber-background-color has-text-color has-background wp-element-button\" href=\"#\" style=\"font-weight:800\">Solicitar demo</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"textColor\":\"bg-2\",\"className\":\"is-style-outline\",\"style\":{\"typography\":{\"fontWeight\":\"800\"}}} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link has-bg-2-color has-text-color wp-element-button\" href=\"#\" style=\"font-weight:800\">Descargar ficha técnica</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n','Ecosistema Atora','','inherit','closed','closed','','6805-revision-v1','','','2026-09-24 00:01:39','2026-09-24 00:01:39','',6805,'http://192.168.1.16:8080/?p=6811',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (6812,1,'2026-09-24 02:28:00','2026-09-24 02:28:00','<!-- wp:group {\"align\":\"full\",\"className\":\"atora-home-institucional\",\"backgroundColor\":\"bg-2\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull atora-home-institucional has-bg-2-background-color has-background\"><!-- wp:group {\"align\":\"full\",\"className\":\"atora-home-hero\",\"backgroundColor\":\"blue-deep\",\"textColor\":\"bg-2\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull atora-home-hero has-bg-2-color has-blue-deep-background-color has-text-color has-background\"><!-- wp:group {\"align\":\"wide\",\"className\":\"atora-home-section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide atora-home-section\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"32px\",\"left\":\"24px\"}}}} -->\n<div class=\"wp-block-columns alignwide are-vertically-aligned-center\"><!-- wp:column {\"width\":\"58%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:58%\"><!-- wp:image {\"id\":6813,\"width\":\"455px\",\"height\":\"auto\",\"aspectRatio\":\"3.462696274272972\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"atora-home-logo\"} -->\n<figure class=\"wp-block-image size-full is-resized atora-home-logo\"><img src=\"http://192.168.1.16:8080/wp-content/uploads/2026/09/Logo-Atora-LMS-ban.jpg\" alt=\"\" class=\"wp-image-6813\" style=\"aspect-ratio:3.462696274272972;width:455px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"className\":\"atora-home-eyebrow atora-home-eyebrow-on-dark\"} -->\n<p class=\"atora-home-eyebrow atora-home-eyebrow-on-dark\">ECOSISTEMA DE ADMINISTRACIÓN DE APRENDIZAJE</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"clamp(2.8rem, 6vw, 5.1rem)\",\"fontWeight\":\"800\",\"lineHeight\":\"1.03\",\"letterSpacing\":\"-0.04em\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|bg-2\"}}}},\"textColor\":\"bg-2\"} -->\n<h1 class=\"wp-block-heading has-bg-2-color has-text-color has-link-color\" style=\"font-size:clamp(2.8rem, 6vw, 5.1rem);font-weight:800;letter-spacing:-0.04em;line-height:1.03\">Toda la vida académica de tu institución, <span class=\"atora-home-accent\">en tu propio servidor.</span></h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.08rem\",\"lineHeight\":\"1.75\"}}} -->\n<p style=\"font-size:1.08rem;line-height:1.75\">LMS, CRM educativo y app móvil en una sola plataforma sobre WordPress. Cursos, cohortes, rúbricas, analítica de riesgo y contenido SCORM/H5P, sin depender de un proveedor externo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"left\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"backgroundColor\":\"amber\",\"textColor\":\"ink\",\"style\":{\"typography\":{\"fontWeight\":\"800\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-ink-color has-amber-background-color has-text-color has-background wp-element-button\" href=\"#\" style=\"font-weight:800\">Solicitar una demo</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"textColor\":\"bg-2\",\"className\":\"is-style-outline\",\"style\":{\"typography\":{\"fontWeight\":\"800\"}}} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link has-bg-2-color has-text-color wp-element-button\" href=\"#\" style=\"font-weight:800\">Ver la academia de prueba</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n\n<!-- wp:separator {\"className\":\"atora-home-hero-sep\",\"backgroundColor\":\"line\"} -->\n<hr class=\"wp-block-separator has-text-color has-line-color has-alpha-channel-opacity has-line-background-color has-background atora-home-hero-sep\"/>\n<!-- /wp:separator -->\n\n<!-- wp:columns {\"className\":\"atora-home-hero-stats\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"24px\"}}}} -->\n<div class=\"wp-block-columns atora-home-hero-stats\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph {\"className\":\"atora-home-stat\"} -->\n<p class=\"atora-home-stat\"><strong>26</strong><br>módulos integrados</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph {\"className\":\"atora-home-stat\"} -->\n<p class=\"atora-home-stat\"><strong>12</strong><br>idiomas</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph {\"className\":\"atora-home-stat\"} -->\n<p class=\"atora-home-stat\"><strong>80%</strong><br>de uso previsto en móvil</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph {\"className\":\"atora-home-stat\"} -->\n<p class=\"atora-home-stat\"><strong>0</strong><br>lock-in: datos y código en tu casa</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"42%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:42%\"><!-- wp:group {\"className\":\"atora-home-dashboard\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-dashboard\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"12px\"}},\"layout\":{\"type\":\"flex\",\"justifyContent\":\"space-between\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"className\":\"atora-home-dashboard-title\"} -->\n<p class=\"atora-home-dashboard-title\"><strong>Panel institucional ·</strong> Diplomado en Comunicación</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"atora-home-badge\"} -->\n<p class=\"atora-home-badge\">Cohorte 2026-II</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"12px\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"atora-home-dashboard-metric\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-dashboard-metric\"><!-- wp:paragraph {\"className\":\"atora-home-dashboard-label\"} -->\n<p class=\"atora-home-dashboard-label\">MATRICULADOS</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"atora-home-dashboard-value\"} -->\n<p class=\"atora-home-dashboard-value\"><strong>1.480</strong></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"atora-home-dashboard-metric\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-dashboard-metric\"><!-- wp:paragraph {\"className\":\"atora-home-dashboard-label\"} -->\n<p class=\"atora-home-dashboard-label\">PROGRESO MEDIO</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"atora-home-dashboard-value\"} -->\n<p class=\"atora-home-dashboard-value\"><strong>63%</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"atora-home-progress\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-progress\"></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"atora-home-dashboard-metric\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-dashboard-metric\"><!-- wp:paragraph {\"className\":\"atora-home-dashboard-label\"} -->\n<p class=\"atora-home-dashboard-label\">EN RIESGO</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"atora-home-dashboard-value atora-home-dashboard-value-amber\"} -->\n<p class=\"atora-home-dashboard-value atora-home-dashboard-value-amber\"><strong>112</strong></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:separator {\"backgroundColor\":\"line\"} -->\n<hr class=\"wp-block-separator has-text-color has-line-color has-alpha-channel-opacity has-line-background-color has-background\"/>\n<!-- /wp:separator -->\n\n<!-- wp:list {\"className\":\"atora-home-dashboard-list\"} -->\n<ul class=\"wp-block-list atora-home-dashboard-list\"><!-- wp:list-item -->\n<li>Fotografía con intención <span class=\"atora-home-chip is-good\">Al día</span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Comunicación visual y redes <span class=\"atora-home-chip is-warn\">14 entregas por calificar</span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Psicología de la comunicación <span class=\"atora-home-chip is-good\">Rúbrica publicada</span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Paquete SCORM · Ética v1.2 <span class=\"atora-home-chip is-good\">Sincronizado</span></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"wide\",\"className\":\"atora-home-section atora-home-checkband\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide atora-home-section atora-home-checkband\"><!-- wp:list {\"className\":\"atora-home-checklist\"} -->\n<ul class=\"wp-block-list atora-home-checklist\"><!-- wp:list-item -->\n<li>WordPress abierto</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>SCORM 1.2</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>H5P</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Streaming HLS protegido</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Multi-institución</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>SSO opcional</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>App Android / iOS</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"wide\",\"className\":\"atora-home-section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide atora-home-section\"><!-- wp:paragraph {\"className\":\"atora-home-kicker\"} -->\n<p class=\"atora-home-kicker\">LA PLATAFORMA</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"fontFamily\":\"var:preset|font-family|sora\",\"fontSize\":\"clamp(2rem, 4.4vw, 3.2rem)\",\"fontWeight\":\"800\",\"letterSpacing\":\"-0.03em\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-family:var(--wp--preset--font-family--sora);font-size:clamp(2rem, 4.4vw, 3.2rem);font-weight:800;letter-spacing:-0.03em\">Un solo sistema para enseñar, evaluar, acompañar y administrar</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.08rem\",\"lineHeight\":\"1.7\"}},\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\" style=\"font-size:1.08rem;line-height:1.7\">Cada módulo nace del uso real en una academia en producción. Se instalan juntos y se activan según lo que tu institución necesita.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"atora-home-feature-grid\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-feature-grid\"><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"16px\",\"left\":\"16px\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"atora-home-feature-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-feature-card\"><!-- wp:html /-->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Cursos y programas</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">Lecciones con video, guías, cuestionarios y entregas abiertas. Programas, diplomados y cohortes.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"atora-home-feature-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-feature-card\"><!-- wp:html /-->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Rúbricas y calificación</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">Escalas propias, pesos y ejemplares. La IA sugiere la nota y detecta contenido generado; el docente decide.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"atora-home-feature-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-feature-card\"><!-- wp:html /-->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Grupos y cohortes</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">Separa usuarios por programa, cohorte y curso. Invitaciones masivas para instituciones.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"atora-home-feature-card is-highlight\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-feature-card is-highlight\"><!-- wp:html /-->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Analítica de riesgo</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">Puntaje de riesgo por estudiante y reportes por cohorte para intervenir antes de la deserción.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"16px\",\"left\":\"16px\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"atora-home-feature-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-feature-card\"><!-- wp:html /-->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Video protegido</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">Streaming HLS con tokens y marca de agua por estudiante. Compatible con YouTube, Vimeo, Drive y CDN.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"atora-home-feature-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-feature-card\"><!-- wp:html /-->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Biblioteca SCORM y H5P</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">Contenido reutilizable y versionable, compartible entre facultades o instituciones.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"atora-home-feature-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-feature-card\"><!-- wp:html /-->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">App móvil con modo offline</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">Descargas que elige el estudiante; las tareas se suben al recuperar conexión con su fecha real.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"atora-home-feature-card\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-feature-card\"><!-- wp:html /-->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">CRM educativo</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">Seguimiento de aspirantes y estudiantes, mensajería académica por WhatsApp y Telegram.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"atora-home-section atora-home-forwho\",\"backgroundColor\":\"bg-2\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull atora-home-section atora-home-forwho has-bg-2-background-color has-background\"><!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:paragraph {\"className\":\"atora-home-kicker\"} -->\n<p class=\"atora-home-kicker\">PARA QUIÉN</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"fontFamily\":\"var:preset|font-family|sora\",\"fontSize\":\"clamp(2rem, 4.4vw, 3.2rem)\",\"fontWeight\":\"800\",\"letterSpacing\":\"-0.03em\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-family:var(--wp--preset--font-family--sora);font-size:clamp(2rem, 4.4vw, 3.2rem);font-weight:800;letter-spacing:-0.03em\">Pensado para tres realidades distintas</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"16px\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"atora-home-segment\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-segment\"><!-- wp:group {\"className\":\"atora-home-segment-head\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-segment-head\"><!-- wp:paragraph {\"className\":\"atora-home-segment-kicker\"} -->\n<p class=\"atora-home-segment-kicker\">UNIVERSIDADES</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Facultades, cohortes y miles de estudiantes</h3>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:list {\"className\":\"atora-home-bullets\"} -->\n<ul class=\"wp-block-list atora-home-bullets\"><!-- wp:list-item -->\n<li>Instalaciones dimensionadas por volumen (hasta ~10.000 personas por instancia)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>SSO con Microsoft Entra, portafolios y reportes académicos</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Datos en servidores propios o en colocation local</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"atora-home-segment\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-segment\"><!-- wp:group {\"className\":\"atora-home-segment-head\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-segment-head\"><!-- wp:paragraph {\"className\":\"atora-home-segment-kicker\"} -->\n<p class=\"atora-home-segment-kicker\">ACADEMIAS Y CENTROS</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Programas continuos con matrícula abierta</h3>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:list {\"className\":\"atora-home-bullets\"} -->\n<ul class=\"wp-block-list atora-home-bullets\"><!-- wp:list-item -->\n<li>Venta de cursos, diplomados y ofertas especiales</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Mentores con perfil público y comunidad</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Certificados y seguimiento del progreso</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"atora-home-segment\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-segment\"><!-- wp:group {\"className\":\"atora-home-segment-head\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-segment-head\"><!-- wp:paragraph {\"className\":\"atora-home-segment-kicker\"} -->\n<p class=\"atora-home-segment-kicker\">FORMACIÓN CORPORATIVA</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Capacitación medible para equipos</h3>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:list {\"className\":\"atora-home-bullets\"} -->\n<ul class=\"wp-block-list atora-home-bullets\"><!-- wp:list-item -->\n<li>Rutas por área y cargo, con cumplimiento y vencimientos</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Contenido SCORM heredado sin reconvertir</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Analítica por sede y por gerencia</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"wide\",\"className\":\"atora-home-section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide atora-home-section\"><!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"24px\"}}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-top\"><!-- wp:column {\"width\":\"55%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:55%\"><!-- wp:paragraph {\"className\":\"atora-home-kicker\"} -->\n<p class=\"atora-home-kicker\">TECNOLOGÍA Y CONFIANZA</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"fontFamily\":\"var:preset|font-family|sora\",\"fontSize\":\"clamp(2rem, 4.6vw, 3.4rem)\",\"fontWeight\":\"800\",\"letterSpacing\":\"-0.03em\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-family:var(--wp--preset--font-family--sora);font-size:clamp(2rem, 4.6vw, 3.4rem);font-weight:800;letter-spacing:-0.03em\">Abierto, auditado y sin dependencia de terceros</h2>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"className\":\"atora-home-trust\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-trust\"><!-- wp:group {\"className\":\"atora-home-trust-item\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group atora-home-trust-item\"><!-- wp:group {\"className\":\"atora-home-dot\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-dot\"></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"className\":\"atora-home-trust-title\"} -->\n<p class=\"atora-home-trust-title\"><strong>Tus datos, tu servidor</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">Se instala en la infraestructura que tú eliges. Si un día te vas, te llevas todo.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"atora-home-trust-item\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group atora-home-trust-item\"><!-- wp:group {\"className\":\"atora-home-dot\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-dot\"></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"className\":\"atora-home-trust-title\"} -->\n<p class=\"atora-home-trust-title\"><strong>Seguridad auditada</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">Auditorías externas y series de endurecimiento sobre REST, autenticación y permisos.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"atora-home-trust-item\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group atora-home-trust-item\"><!-- wp:group {\"className\":\"atora-home-dot\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-dot\"></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"className\":\"atora-home-trust-title\"} -->\n<p class=\"atora-home-trust-title\"><strong>Multi-institución desde el diseño</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">Una arquitectura preparada para varias sedes o instituciones con administración separada.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"atora-home-trust-item\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group atora-home-trust-item\"><!-- wp:group {\"className\":\"atora-home-dot\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-dot\"></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"className\":\"atora-home-trust-title\"} -->\n<p class=\"atora-home-trust-title\"><strong>Interoperable</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">SCORM 1.2, H5P y puentes LTI para convivir con Canvas o Moodle sin quedar atrapado.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"45%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:45%\"><!-- wp:group {\"className\":\"atora-home-arch\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group atora-home-arch\"><!-- wp:paragraph {\"className\":\"atora-home-arch-kicker\"} -->\n<p class=\"atora-home-arch-kicker\">ARQUITECTURA DEL ECOSISTEMA</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"atora-home-arch-item\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"space-between\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group atora-home-arch-item\"><!-- wp:paragraph -->\n<p><strong>App móvil Android / iOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">offline · estudiante y docente</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"atora-home-arch-item\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"space-between\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group atora-home-arch-item\"><!-- wp:paragraph -->\n<p><strong>Tema ATORA</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"ink-2\"} -->\n<p class=\"has-ink-2-color has-text-color\">sitio público y academia</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"atora-home-arch-item is-active\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"space-between\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group atora-home-arch-item is-active\"><!-- wp:paragraph -->\n<p><strong>ATORA LMS + CRM</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>26 módulos · API REST</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"atora-home-arch-item\",\"layout\":{\"type\":\"flex\",\"justifyCon